import java.nio.file.*;import java.util.*;import com.fasterxml.jackson.databind.*;import com.totaldocs.format.web.util.*;import co.sirius.format.pontof.controller.ler.PontoFLer;
public class GeometryProbe {
 public static void main(String[] args)throws Exception {
  ObjectMapper mapper=new ObjectMapper();Path file=Path.of(args[0]);var app=PontoFTojson.convertFromPontoF(new PontoFLer(file.toFile()).execute(),file.toString());JsonNode layout=mapper.valueToTree(app);var issues=LayoutGeometry.inspect(layout);int overlaps=0;var items=layout.at("/listaDocumentos/0/layout");
  for(int i=0;i<items.size();i++)if(items.get(i).path("type").asText().equals("text"))for(int j=i+1;j<items.size();j++)if(items.get(j).path("type").asText().equals("text")){var a=LayoutGeometry.bounds(items.get(i));var b=LayoutGeometry.bounds(items.get(j));if(Math.min(a.right(),b.right())-Math.max(a.left(),b.left())>.1&&Math.min(a.bottom(),b.bottom())-Math.max(a.top(),b.top())>.1)overlaps++;}
  var report=new LinkedHashMap<String,Object>();report.put("file",file.toString());report.put("issues",issues);report.put("textBoxOverlaps",overlaps);report.put("layout",layout);Files.writeString(Path.of(args[1]),mapper.writerWithDefaultPrettyPrinter().writeValueAsString(report));System.out.println("Bounds issues="+issues.size()+"; overlapping text pairs="+overlaps);
  if(args.length>2&&args[2].equals("assert")){if(!issues.isEmpty()||overlaps>0)throw new AssertionError("Letter geometry invalid");var editor=new NativeEditor(mapper);var snapshot=editor.inspect(file.toFile());var target=snapshot.inventory().stream().filter(x->x.get("type").equals("text")).findFirst().orElseThrow();var request=mapper.createObjectNode().put("fileHash",snapshot.hash());request.putArray("operations").addObject().put("action","edit").put("targetId",target.get("id").toString()).putObject("changes").put("y",-20);try{editor.prepare(file.toFile(),request);throw new AssertionError("Out of bounds proposal was accepted");}catch(IllegalArgumentException expected){if(!expected.getMessage().contains("limite"))throw expected;System.out.println("Native plan rejected out-of-bounds edit after reread");}}
 }
}
